set -euo pipefail
python - <<'PY'
import json
p='/output/candidate.json'
x=json.load(open(p))
f=x['j']['intent']['intent_function']
old=f['body']
assert [n['id'] for n in old]==['n0','n1','n2','n3','n4']
assert old[1]['op']=='map_unary' and old[1]['attrs']=={'fn':'tanh'}
# Focused repair: replace unsupported direct tanh realization with the
# equivalent sigmoid(2*x)-sigmoid(-2*x) graph.
f['body']=[
 {'op':'map_binary','id':'n0','result':'v0','operands':['t1','t0'],'attrs':{'fn':'mul'}},
 {'op':'map_binary','id':'n1','result':'v1','operands':['v0','v0'],'attrs':{'fn':'add'}},
 {'op':'map_unary','id':'n2','result':'v2','operands':['v1'],'attrs':{'fn':'sigmoid'}},
 {'op':'map_unary','id':'n3','result':'v3','operands':['v1'],'attrs':{'fn':'neg'}},
 {'op':'map_unary','id':'n4','result':'v4','operands':['v3'],'attrs':{'fn':'sigmoid'}},
 {'op':'map_binary','id':'n5','result':'v5','operands':['v2','v4'],'attrs':{'fn':'sub'}},
 {'op':'map_binary','id':'n6','result':'v6','operands':['v5','t2'],'attrs':{'fn':'mul'}},
 {'op':'map_binary','id':'n7','result':'v7','operands':['v6','t3'],'attrs':{'fn':'add'}},
 {'op':'select','id':'n8','result':'t5','operands':['t4','v7','v6']},
]
x['j']['node_ids']={f'n{i}':f'body[{i}]' for i in range(9)}
# Remap old downstream node references to the repaired sequential IDs.
node_map={'n0':'n0','n1':'n5','n2':'n6','n3':'n7','n4':'n8'}
def remap_node_fields(v):
 if isinstance(v,dict):
  for k,val in list(v.items()):
   if k in ('node_ref','update_node_ref') and isinstance(val,str) and val in node_map:
    v[k]=node_map[val]
   else: remap_node_fields(val)
 elif isinstance(v,list):
  for z in v: remap_node_fields(z)
remap_node_fields(x['j']['boundary'])
x['j']['scopes'][0]['definitions']=['t0','t1','t2','t3','t4','t5']+[f'v{i}' for i in range(8)]
# Preserve declaration order while inserting four additional realization instances.
pi=x['pi']
def shift_i(s):
 if isinstance(s,str) and s.startswith('i') and s[1:].isdigit() and int(s[1:])>=26:
  return 'i'+str(int(s[1:])+4)
 return s
for sec in ('routes','order','sharing','refinements'):
 def walk(v):
  if isinstance(v,dict):
   for k,val in list(v.items()):
    if isinstance(val,str): v[k]=shift_i(val)
    elif isinstance(val,list): v[k]=[shift_i(z) if isinstance(z,str) else z for z in val]; [walk(z) for z in v[k] if isinstance(z,(dict,list))]
    else: walk(val)
  elif isinstance(v,list):
   for z in v: walk(z)
 walk(pi[sec])
new_instances=[]
for inst in pi['instances']:
 old_id=int(inst['id'][1:])
 if old_id==26:
  new_instances.extend([
   {'id':'i26','semantic_ref':'n1','region':'r1','mechanism':'realize'},
   {'id':'i27','semantic_ref':'n2','region':'r1','mechanism':'realize'},
   {'id':'i28','semantic_ref':'n3','region':'r1','mechanism':'realize'},
   {'id':'i29','semantic_ref':'n4','region':'r1','mechanism':'realize'},
  ])
 if old_id>=26: inst['id']='i'+str(old_id+4)
 if inst['semantic_ref'] in node_map: inst['semantic_ref']=node_map[inst['semantic_ref']]
 new_instances.append(inst)
pi['instances']=new_instances
# Replace the old direct n0->tanh route with the equivalent realization subgraph.
old_direct={'source':'i25','target':'i30','slots':[0]}
assert old_direct in pi['routes']
pi['routes'].remove(old_direct)
insert_at=next(i for i,r in enumerate(pi['routes']) if r.get('source')=='i30' and r.get('target')=='i31')
pi['routes'][insert_at:insert_at]=[
 {'source':'i25','target':'i26','slots':[0,1]},
 {'source':'i26','target':'i27','slots':[0]},
 {'source':'i26','target':'i28','slots':[0]},
 {'source':'i28','target':'i29','slots':[0]},
 {'source':'i27','target':'i30','slots':[0]},
 {'source':'i29','target':'i30','slots':[1]},
]
# The doubled value has two distinct consumers.
pi['sharing'].append({'source':'i26','consumers':['i27','i28']})
with open(p,'w') as out:
 json.dump(x,out,indent=2,sort_keys=True)
 out.write('\n')
print('wrote focused tanh realization repair')
print('body ids:', [n['id'] for n in f['body']])
print('instances:', len(pi['instances']), 'routes:', len(pi['routes']))
PY

